import React, {Component} from 'react';
import {Container, Collapse,ListGroup,ListGroupItem,Button} from 'reactstrap';
import {CSSTransition, TransitionGroup} from 'react-transition-group';
import { v4 as uuidv4 } from 'uuid';

class ShoppingList extends Component {
    state= {
        items: [
            {id:uuidv4(), name: 'Juice'},
            {id:uuidv4(), name: 'Mushrooms'},
            {id:uuidv4(), name: 'Jalepenos'},
            {id:uuidv4(), name: 'Onions'}
        ]
    }
    render(){
        const {items} = this.state;
        return(
            <Container>
                <Button color="dark" style={{marginBottom:'2rem'}} onClick={ ()=>{
                    const name = prompt('Enter Item');
                    if(name){
                        this.setState(state=>({
                            items: [...state.items, {id:uuidv4(), name}]
                        }));
                    }
                }}>Add Item</Button>
                <ListGroup>
                    <TransitionGroup className="shopping-list">
                        {items.map(({id,name,})=>(
                            <CSSTransition key={id} timeout={6000} classNames="fade">
                                <ListGroupItem>
                                    <Button className="remove-btn" color="danger" size="sm" onClick={()=>{this.setState(
                                        state=>({
                                            items:state.items.filter(item=>item.id!==id)        
                                        })
                                    );}}>&times;</Button>
                                    {name}
                                </ListGroupItem>
                            </CSSTransition>
                        ))}
                    </TransitionGroup>
                </ListGroup>
            </Container>
        );
    }
}

export default ShoppingList;
